#!/usr/bin/env python3
"""Verify t21b's PE-bounded control-flow audit and count scopes."""
from __future__ import annotations

import argparse
import json
import sys
from pathlib import Path

OUT = Path(__file__).resolve().parent
EXPECTED_STATUS = "partial_control_flow_audit_complete_row_cursor_unreconciled"
EXPECTED_EDITOR_SHA = "b82ebe8e032f20171e813c02f53084dc0ac2c43bc8346beb742418efaadadab4"


def selftest() -> bool:
    return EXPECTED_STATUS.startswith("partial_control_flow_") and len(EXPECTED_EDITOR_SHA) == 64


def verify() -> list[str]:
    errors: list[str] = []
    path = OUT / "control_flow.json"
    if not path.is_file():
        return ["missing control_flow.json"]
    try:
        doc = json.loads(path.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        return [f"invalid control_flow.json: {exc}"]
    if doc.get("status") != EXPECTED_STATUS:
        errors.append("control-flow status no longer preserves the unreconciled cursor")
    if doc.get("editor_sha256") != EXPECTED_EDITOR_SHA:
        errors.append("editor.exe SHA-256 differs from the frozen audit")
    comparison = doc.get("linear_scan_comparison", {})
    expected_counts = {
        "t05_window_stream_call_count": 41,
        "t01h_reported_stream_call_count": 21,
        "t01h_stream_call_site_records": 8,
        "t01h_stream_call_sites_matching_cfg_transfer_sites": 8,
        "t01h_stream_call_sites_not_matching_cfg": 0,
        "club_cfg_reachable_stream_transfer_count": 41,
    }
    for key, expected in expected_counts.items():
        if comparison.get(key) != expected:
            errors.append(f"{key}={comparison.get(key)!r}, expected {expected!r}")
    if comparison.get("t05_window_byte_span") != "0x2000":
        errors.append("t05 scan window is not 0x2000 bytes")
    if comparison.get("t05_scan_end_exclusive") != "0xe5c7a0":
        errors.append("t05 scan end does not match the recorded 0x2000-byte window")
    classes = {item.get("class"): item for item in doc.get("classes", [])}
    if set(classes) != {"CLUB", "LEAGUE_BODY_CLUB"}:
        errors.append(f"unexpected reader classes: {sorted(classes)}")
    bounds = {
        "CLUB": ("0xe5a7a0", "0xe5bfca", 41, 167, 35),
        "LEAGUE_BODY_CLUB": ("0x43beba0", "0x43bec73", 2, 3, 1),
    }
    for name, (begin, end, transfers, branches, backedges) in bounds.items():
        cfg = classes[name].get("cfg", {})
        extent = cfg.get("function_extent", {})
        if extent.get("begin_file_offset") != begin or extent.get("end_file_offset_exclusive") != end:
            errors.append(f"{name} PE runtime-function extent changed")
        for key, expected in (("reachable_stream_transfer_count", transfers),
                              ("conditional_branch_count", branches),
                              ("backedge_count", backedges)):
            if cfg.get(key) != expected:
                errors.append(f"{name} {key}={cfg.get(key)!r}, expected {expected!r}")
        if len(cfg.get("stream_transfers", [])) != transfers:
            errors.append(f"{name} transfer record count does not match summary")
    if doc.get("row_class_discriminator", {}).get("status") != "negative_not_established":
        errors.append("row class discriminator was promoted")
    if doc.get("row_class_discriminator", {}).get("row_coordinate_mapping_count") != 0:
        errors.append("t21b unexpectedly reports row-coordinate mappings")
    if doc.get("Cccn", {}).get("status") != "unpromoted":
        errors.append("Cccn was promoted")
    for item in classes.values():
        for transfer in item.get("cfg", {}).get("stream_transfers", []):
            if transfer.get("width_source") == "same_basic_block_mov_r8d" and transfer.get("width_before_call") is None:
                errors.append(f"local width source has null width at {transfer.get('file_offset')}")
    return errors


def main() -> int:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--selftest", action="store_true", help="run deterministic checks")
    args = parser.parse_args()
    if args.selftest:
        ok = selftest()
        print("t21b verify selftest: " + ("PASS" if ok else "FAIL"))
        return 0 if ok else 1
    try:
        errors = verify()
    except (OSError, TypeError, KeyError) as exc:
        print(f"fatal: {exc}", file=sys.stderr)
        return 2
    if errors:
        for error in errors:
            print("FAIL: " + error)
        return 1
    print("PASS (partial): PE-bounded CFG counts and count scopes verified; row cursor remains unreconciled.")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

#!/usr/bin/env python3
"""Audit club row framing and independently recheck RTTI reader evidence."""
from __future__ import annotations

import argparse
import hashlib
import importlib.util
import json
import struct
import sys
from collections import Counter
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
EDITOR = Path(r"D:\tmp2b\fm24\input\editor.exe")
RTTI_CENSUS = ROOT / "scratch/t01/inbox/t01h/output.json"
OUT = ROOT / "scratch/t21/out"
EXPECTED_ROWS = 84259
COMPACT_ROWS = {69706, 69707, 69708}


def load_json(path: Path) -> Any:
    return json.loads(path.read_text(encoding="utf-8"))


def import_script(name: str, path: Path):
    spec = importlib.util.spec_from_file_location(name, path)
    if spec is None or spec.loader is None:
        raise RuntimeError(f"cannot import {path}")
    module = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(module)
    return module


def parse_standard_row(raw: bytes, start: int, ordinal: int) -> dict[str, Any] | None:
    if start + 30 > len(raw):
        return None
    try:
        ids = struct.unpack_from("<4I", raw, start)
        full_len = struct.unpack_from("<I", raw, start + 26)[0]
        if full_len > 4096:
            return None
        full_start = start + 30
        short_len_at = full_start + full_len
        if short_len_at + 4 > len(raw):
            return None
        full_name = raw[full_start:short_len_at].decode("utf-8")
        short_len = struct.unpack_from("<I", raw, short_len_at)[0]
        if short_len > 4096:
            return None
        short_start = short_len_at + 4
        identity_at = short_start + short_len + 3
        if identity_at + 13 > len(raw):
            return None
        short_name = raw[short_start:short_start + short_len].decode("utf-8")
        row_id, duni_a, duni_b = struct.unpack_from("<III", raw, identity_at)
        marker = raw[identity_at + 12]
        if row_id != ordinal or duni_a != duni_b or marker not in (0, 12):
            return None
        end = identity_at + 13
        return {
            "ordinal": ordinal, "start": start, "end": end,
            "length": end - start, "standard": True, "ids": ids,
            "full_name": full_name, "short_name": short_name,
            "full_len": full_len, "short_len": short_len,
            "identity_at": identity_at, "identity_relative": identity_at - start,
            "duni": duni_a, "marker": marker,
        }
    except (UnicodeDecodeError, struct.error):
        return None


def find_compact_row(raw: bytes, start: int, ordinal: int) -> dict[str, Any]:
    needle = struct.pack("<I", ordinal)
    stop = min(start + 8192, len(raw))
    hits = []
    at = raw.find(needle, start + 20, stop)
    while at >= 0:
        row_id, duni_a, duni_b = struct.unpack_from("<III", raw, at)
        marker = raw[at + 12]
        if row_id == ordinal and duni_a == duni_b and marker in (0, 12):
            hits.append((at, duni_a, marker))
        at = raw.find(needle, at + 1, stop)
    if len(hits) != 1:
        raise ValueError(f"compact row {ordinal}: expected one identity hit, got {len(hits)}")
    identity_at, duni, marker = hits[0]
    if identity_at - start != 42:
        raise ValueError(f"compact row {ordinal}: identity offset {identity_at - start} != 42")
    return {
        "ordinal": ordinal, "start": start, "end": identity_at + 13,
        "length": identity_at + 13 - start, "standard": False,
        "ids": struct.unpack_from("<4I", raw, start),
        "full_name": None, "short_name": None, "full_len": None,
        "short_len": None, "identity_at": identity_at,
        "identity_relative": 42, "duni": duni, "marker": marker,
    }


def walk_club(raw: bytes) -> list[dict[str, Any]]:
    if len(raw) < 22:
        raise ValueError("club payload is shorter than header and footer")
    count = struct.unpack_from("<I", raw, 8)[0]
    if count != EXPECTED_ROWS:
        raise ValueError(f"club row count {count} != expected {EXPECTED_ROWS}")
    footer_at = len(raw) - 8
    rows = []
    pos = 14
    for ordinal in range(count):
        row = (find_compact_row(raw, pos, ordinal) if ordinal in COMPACT_ROWS
               else parse_standard_row(raw, pos, ordinal))
        if row is None:
            raise ValueError(f"standard row parse failed at ordinal {ordinal}, offset {pos:#x}")
        if row["end"] <= pos or row["end"] > footer_at:
            raise ValueError(f"invalid row end at ordinal {ordinal}: {row['end']:#x}")
        rows.append(row)
        pos = row["end"]
    if pos != footer_at:
        raise ValueError(f"row end {pos:#x} does not meet footer {footer_at:#x}")
    return rows


def profile_rows(raw: bytes, rows: list[dict[str, Any]]) -> dict[str, Any]:
    relations = Counter()
    byte20 = Counter()
    marker_counts = Counter()
    row_lengths = Counter()
    for row in rows:
        start = row["start"]
        values = {off: struct.unpack_from("<I", raw, start + off)[0]
                  for off in (0, 4, 8, 12, 16)}
        for a, b in ((0, 8), (0, 12), (8, 12), (0, 16)):
            relations[f"u32@{a}==u32@{b}"] += values[a] == values[b]
        byte20[raw[start + 20]] += 1
        marker_counts[row["marker"]] += 1
        row_lengths[row["length"]] += 1
    ranges = []
    for label, lo, hi in (("before_69705", 0, 69705), ("from_69705", 69705, len(rows))):
        subset = rows[lo:hi]
        equal_0_8 = sum(row["ids"][0] == row["ids"][2] for row in subset)
        equal_0_12 = sum(row["ids"][0] == row["ids"][3] for row in subset)
        ranges.append({
            "label": label, "ordinal_start_inclusive": lo,
            "ordinal_end_exclusive": hi, "row_count": len(subset),
            "u32_at_0_equals_8": equal_0_8,
            "u32_at_0_equals_8_ratio": equal_0_8 / len(subset) if subset else None,
            "u32_at_0_equals_12": equal_0_12,
        })
    samples = []
    for ordinal in (69704, 69705, 69706, 69707, 69708, 69709, 69710):
        row = rows[ordinal]
        start = row["start"]
        samples.append({
            "ordinal": ordinal, "member_offset": hex(start),
